          '　そう言って、彼は手に持っていた書店の袋を少し持ち上げて見せた。少し透けたビニール袋にはあの東大の赤本が入っていた。葵もそれを見るや、少し目を丸くして（すごっ、分厚っ…）と心の中で小さく呟く。',
