          '　2人は並んで歩き出す。以前なら、心臓が喉から飛び出し、まともに隣を歩くことすら難しかったかもしれない。けれど、今は違う。もちろん、胸の高鳴りは静かに続いているけれど、あの息もできないほどの緊張感は和らいでいた。隣にいる彼の存在を、以前よりも少しだけ落ち着いて感じながら、葵はそっと歩調を合わせた。',
          '　雪は少しだけ勢いを増し、二人の間に、まだ少しぎこちないながらも、穏やかな時間が流れ始める。そんな静けさの中、先に口を開いたのは遥斗だった。',
