          '　遥斗は少し早口になりながら、それでも真剣な眼差しでそう伝えてくれた。彼が自分の絵を見て、そんな風に感じてくれたこと。夏休みの、あの苦しかった時のやり取りを覚えていてくれたこと。その一つ一つが、葵の心の奥深くを温かく満たしていく。嬉しくて、恥ずかしくて、胸がいっぱいで、言葉が出てこない。',
