          '　――その言葉に、葵の胸の奥がきゅっと甘く締め付けられるのを感じた。忘れていたわけではない、あの夜の記憶。彼から直接その言葉を聞くと、抑えていた熱が再び顔に集まってくるのを感じた。あの夏祭りの夜に自覚した特別な気持ちが、ふわりと心をかすめた。',
