          '　「温かい光を見つけるのが上手い」彼が、私をそんな風に見てくれている。その言葉が、甘く、そして少し切なく胸に響く。彼の普段と違う私服姿、ふとした瞬間に見せる大人びた表情、そして、私の内面を理解してくれているような優しい言葉。それらすべてが、夏祭りの夜に確かに感じ、でもあの時は胸にしまっていた、憧れだけではない、葵の中の特別な想いが、再び強く呼び起こされていく。',
          '（…やっぱり、私、遥斗先輩のこと…）',
          '　胸の中で、あの夜に芽生えた気持ちが、静かに、そして輪郭を持って大きく育っていくのが自分でも感じ取れた。',
