          '　一人になると、さっきまで遥斗には悟られないようにしていた熱が一気に込み上げてくる。雪が舞う中、火照った頬は冷えるどころか、ますます熱くなっていくようだった。',
          '　自分の中で確信したばかりの、遥斗への「好き」という気持ち。その大きさと熱量に、葵はただただ戸惑い、胸の高鳴りを抑えることができなかった。12月になったばかりの初雪と共に訪れた確かな恋心は、降りしきる雪のように、静かに、しかし深く、葵の世界を白く、そして温かく染め上げていくようだった。',
